import { z } from 'zod';
import { MAX_MULTIPLIER, MIN_MULTIPLIER } from './limits.js';
export const PlanSchema = z.enum(['30d', '365d']);
/** Identifier of a site adapter, e.g. "onexbet". Lowercase, short, no free text. */
export const SiteIdSchema = z.string().regex(/^[a-z0-9_-]{1,32}$/, 'invalid site id');
/** Device id generated by the extension at install time (random UUID, no hardware data). */
export const DeviceIdSchema = z.uuid();
export const IsoDateTimeSchema = z.iso.datetime({ offset: true });
/** A crash multiplier with at most 2 decimal places. */
export const MultiplierSchema = z
    .number()
    .finite()
    .min(MIN_MULTIPLIER)
    .max(MAX_MULTIPLIER)
    .refine((v) => Math.abs(Math.round(v * 100) - v * 100) < 1e-6, 'at most 2 decimal places');
/**
 * Activation code as typed by a user: "AVX-XXXX-XXXX-XXXX-XXXX-XXXX".
 * Clients may send it with or without prefix, dashes, spaces or lower case;
 * the server normalizes it. The schema only bounds the size.
 */
export const ActivationCodeInputSchema = z.string().trim().min(16).max(40);
export const SubscriptionStatusSchema = z.enum(['active', 'expired', 'revoked']);
export const SubscriptionViewSchema = z.object({
    plan: PlanSchema,
    status: SubscriptionStatusSchema,
    activatedAt: IsoDateTimeSchema,
    expiresAt: IsoDateTimeSchema,
    deviceLimit: z.number().int().positive(),
    devicesInUse: z.number().int().nonnegative(),
});
export const HealthResponseSchema = z.object({
    status: z.literal('ok'),
    version: z.string(),
    time: IsoDateTimeSchema,
});
